  const memoryCounts = useMemo(() => {
    const out: Record<string, number> = {}
    for (const n of filteredNodes) {
      if ((n.node_type ?? 'memory') === 'memory') {
        const t = (n.memory_type as string) || 'fact'
        out[t] = (out[t] ?? 0) + 1
